import{_ as a,a0 as l,w as r,s as p,I as t,x as s,a1 as o,A as n,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"什么是僵尸进程，如何找到并杀掉僵尸进程？ | LCTT x X-CMD","titleTemplate":false,"description":"什么是僵尸进程，如何找到并杀掉僵尸进程？ | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"什么是僵尸进程，如何找到并杀掉僵尸进程？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什么是僵尸进程，如何找到并杀掉僵尸进程？ | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171211 What Are Zombie Processes And How To Find & Kill Zombie Processes-","title":"什么是僵尸进程，如何找到并杀掉僵尸进程？","tag":"201712","desc":""},"relativePath":"201712/20171211 What Are Zombie Processes And How To Find & Kill Zombie Processes-.md","filePath":"[post].md"}'),u={name:"201712/20171211 What Are Zombie Processes And How To Find & Kill Zombie Processes-.md"};function m(b,e,h,g,f,w){const i=l("Link");return r(),p("div",null,[e[15]||(e[15]=t("h1",{id:"什么是僵尸进程-如何找到并杀掉僵尸进程",tabindex:"-1"},[s("什么是僵尸进程，如何找到并杀掉僵尸进程？ "),t("a",{class:"header-anchor",href:"#什么是僵尸进程-如何找到并杀掉僵尸进程","aria-label":"Permalink to “什么是僵尸进程，如何找到并杀掉僵尸进程？”"},"​")],-1)),t("p",null,[o(i,{href:"http://www.linuxandubuntu.com/home/what-are-zombie-processes-and-how-to-find-kill-zombie-processes"},{default:n(()=>[...e[0]||(e[0]=[t("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/what-are-the-zombie-processes_orig.jpg",alt:"What Are Zombie Processes And How To Find & Kill Zombie Processes？"},null,-1)])]),_:1})]),e[16]||(e[16]=t("p",null,[s("如果你经常使用 Linux，你应该遇到这个术语“"),t("ruby",null,[s("僵尸进程"),t("rt",null,"Zombie Processes")]),s("”。 那么什么是僵尸进程？ 它们是怎么产生的？ 它们是否对系统有害？ 我要怎样杀掉这些进程？ 下面将会回答这些问题。")],-1)),e[17]||(e[17]=t("h3",{id:"什么是僵尸进程",tabindex:"-1"},[s("什么是僵尸进程？ "),t("a",{class:"header-anchor",href:"#什么是僵尸进程","aria-label":"Permalink to “什么是僵尸进程？”"},"​")],-1)),e[18]||(e[18]=t("p",null,"我们都知道进程的工作原理。我们启动一个程序，开始我们的任务，然后等任务结束了，我们就停止这个进程。 进程停止后， 该进程就会从进程表中移除。",-1)),e[19]||(e[19]=t("p",null,[s("你可以通过 "),t("code",null,"System-Monitor"),s(" 查看当前进程。")],-1)),t("p",null,[o(i,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/linux-check-zombie-processes_orig.jpg"},{default:n(()=>[...e[1]||(e[1]=[t("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/linux-check-zombie-processes_orig.jpg",alt:""},null,-1)])]),_:1})]),e[20]||(e[20]=d('<p>但是，有时候有些程序即使执行完了也依然留在进程表中。</p><p>那么，这些完成了生命周期但却依然留在进程表中的进程，我们称之为 “僵尸进程”。</p><h3 id="它们是如何产生的" tabindex="-1">它们是如何产生的？ <a class="header-anchor" href="#它们是如何产生的" aria-label="Permalink to “它们是如何产生的？”">​</a></h3><p>当你运行一个程序时，它会产生一个父进程以及很多子进程。 所有这些子进程都会消耗内核分配给它们的内存和 CPU 资源。</p><p>这些子进程完成执行后会发送一个 Exit 信号然后死掉。这个 Exit 信号需要被父进程所读取。父进程需要随后调用 <code>wait</code> 命令来读取子进程的退出状态，并将子进程从进程表中移除。</p><p>若父进程正确第读取了子进程的 Exit 信号，则子进程会从进程表中删掉。</p><p>但若父进程未能读取到子进程的 Exit 信号，则这个子进程虽然完成执行处于死亡的状态，但也不会从进程表中删掉。</p><h3 id="僵尸进程对系统有害吗" tabindex="-1">僵尸进程对系统有害吗？ <a class="header-anchor" href="#僵尸进程对系统有害吗" aria-label="Permalink to “僵尸进程对系统有害吗？”">​</a></h3><p><strong>不会</strong>。由于僵尸进程并不做任何事情， 不会使用任何资源也不会影响其它进程， 因此存在僵尸进程也没什么坏处。 不过由于进程表中的退出状态以及其它一些进程信息也是存储在内存中的，因此存在太多僵尸进程有时也会是一些问题。</p><p><strong>你可以想象成这样：</strong></p><p>“你是一家建筑公司的老板。你每天根据工人们的工作量来支付工资。 有一个工人每天来到施工现场，就坐在那里， 你不用付钱， 他也不做任何工作。 他只是每天都来然后呆坐在那，仅此而已！”</p><p>这个工人就是僵尸进程的一个活生生的例子。<strong>但是</strong>， 如果你有很多僵尸工人， 你的建设工地就会很拥堵从而让那些正常的工人难以工作。</p><h3 id="那么如何找出僵尸进程呢" tabindex="-1">那么如何找出僵尸进程呢？ <a class="header-anchor" href="#那么如何找出僵尸进程呢" aria-label="Permalink to “那么如何找出僵尸进程呢？”">​</a></h3><p>打开终端并输入下面命令:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ps aux | grep Z</span></span></code></pre></div><p>会列出进程表中所有僵尸进程的详细内容。</p><h3 id="如何杀掉僵尸进程" tabindex="-1">如何杀掉僵尸进程？ <a class="header-anchor" href="#如何杀掉僵尸进程" aria-label="Permalink to “如何杀掉僵尸进程？”">​</a></h3><p>正常情况下我们可以用 <code>SIGKILL</code> 信号来杀死进程，但是僵尸进程已经死了， 你不能杀死已经死掉的东西。 因此你需要输入的命令应该是</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kill -s SIGCHLD pid</span></span></code></pre></div><p>将这里的 pid 替换成父进程的进程 id，这样父进程就会删除所有以及完成并死掉的子进程了。</p><p><strong>你可以把它想象成：</strong></p><p>&quot;你在道路中间发现一具尸体，于是你联系了死者的家属，随后他们就会将尸体带离道路了。&quot;</p><p>不过许多程序写的不是那么好，无法删掉这些子僵尸（否则你一开始也见不到这些僵尸了）。 因此确保删除子僵尸的唯一方法就是杀掉它们的父进程。</p><hr>',24)),t("p",null,[e[3]||(e[3]=s("via: ",-1)),o(i,{href:"http://www.linuxandubuntu.com/home/what-are-zombie-processes-and-how-to-find-kill-zombie-processes"},{default:n(()=>[...e[2]||(e[2]=[s("http://www.linuxandubuntu.com/home/what-are-zombie-processes-and-how-to-find-kill-zombie-processes",-1)])]),_:1})]),t("p",null,[e[7]||(e[7]=s("作者：",-1)),o(i,{href:"http://www.linuxandubuntu.com"},{default:n(()=>[...e[4]||(e[4]=[s("linuxandubuntu",-1)])]),_:1}),e[8]||(e[8]=s(" 译者：",-1)),o(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[5]||(e[5]=[s("lujun9972",-1)])]),_:1}),e[9]||(e[9]=s(" 校对：",-1)),o(i,{href:"https://github.com/wxy"},{default:n(()=>[...e[6]||(e[6]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=s("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原创编译，",-1)),o(i,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[s("Linux中国",-1)])]),_:1}),e[14]||(e[14]=s(" 荣誉推出",-1))])])}const P=a(u,[["render",m]]);export{T as __pageData,P as default};
